import r2pipe
import json

def analyze_binary():
    r2 = r2pipe.open('./ctf_files/kvm/challenge')
    r2.cmd('aaa')  # Analyze all

    # Get the main function
    main_json = r2.cmdj('pdj @ main')

    # Find references to our key string
    refs = r2.cmdj('/j w}5o1t37fi?cbdgr2emnx{as64hlu')

    # Get cross references
    if refs:
        for ref in refs:
            xrefs = r2.cmdj(f'axtj @ {ref["offset"]}')
            print(f"String referenced at: {hex(ref['offset'])}")
            if xrefs:
                for xref in xrefs:
                    print(f"Referenced from: {hex(xref['from'])}")

    # Get the function that handles VM setup
    funcs = r2.cmdj('aflj')
    for func in funcs:
        # Look for functions that call mmap or ioctl
        fcn_details = r2.cmdj(f'pdfj @ {func["offset"]}')
        if fcn_details:
            for instr in fcn_details:
                if isinstance(instr, dict) and 'opcode' in instr:
                    if 'mmap' in instr['opcode'] or 'ioctl' in instr['opcode']:
                        print(f"\nAnalyzing function at {hex(func['offset'])}:")
                        print(r2.cmd(f'pdf @ {func["offset"]}'))

    r2.quit()

if __name__ == '__main__':
    analyze_binary()

